command:
$ErrorActionPreference="Stop"
Set-Location -LiteralPath $env:FLYEXPLORER_CANONICAL_CHECKOUT
$before=& gh api repos/tngkrwlsmd/flyExplorer/immutable-releases
if($LASTEXITCODE -ne 0){throw "immutable release status read failed"}
Write-Host ("IMMUTABLE_RELEASES_BEFORE="+$before)
& gh api --method PUT repos/tngkrwlsmd/flyExplorer/immutable-releases
if($LASTEXITCODE -ne 0){throw "failed to enable immutable releases"}
$after=& gh api repos/tngkrwlsmd/flyExplorer/immutable-releases
if($LASTEXITCODE -ne 0){throw "immutable release status verification failed"}
Write-Host ("IMMUTABLE_RELEASES_AFTER="+$after)
$parsed=$after | ConvertFrom-Json
if(-not $parsed.enabled){throw "immutable releases remain disabled"}
Write-Host "IMMUTABLE_RELEASES_ENABLE=PASS"
